import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as P,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"路径 MTU 发现","description":"","frontmatter":{"title":"路径 MTU 发现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pmtud.md","filePath":"cs/pmtud.md","lastUpdated":1789023840000}'),M={name:"cs/pmtud.md"};function c(T,a,h,C,u,m){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="路径-mtu-发现" tabindex="-1">路径 MTU 发现 <a class="header-anchor" href="#路径-mtu-发现" aria-label="Permalink to &quot;路径 MTU 发现&quot;">​</a></h1><div class="epigraph"><p>把 DF 置位，让太小的一跳用 ICMP 报告；过滤 ICMP 就把发现变成黑洞，主机只能靠探测或保守 1280/576。</p><footer>—— 据 RFC 1191；RFC 8201 IPv6 PMTUD；RFC 4821 分组化 PLPMTUD 整理</footer></div><p><a href="/cs/jumbo-mtu">巨帧</a> 与 <a href="/cs/gre-tunnels">GRE</a>、<a href="/cs/vxlan-overlay">VXLAN</a>、<a href="/cs/ipv6-transition">IPv6 过渡</a> 都吃 MTU。<a href="/cs/ipv6-transition">上一课</a> 留下隧道头税。缺口是<strong>沿路最小 MTU 怎么发现</strong>。本课不把 traceroute 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>源不知道路径。IPv4 PMTUD：DF=1，路由器丢弃并 ICMP Fragmentation Needed。IPv6 无源分片，只能这样。黑洞：中间丢大包且不回 ICMP（防火墙「安全」），TCP 卡住。PLPMTUD：传输层用探测与丢失推断，不依赖 ICMP。MSS 钳制后课会在边缘傻切，是权宜。</p><p>不要把 PMTUD 写成一次性：路由变化、ECMP 不同成员，最小 MTU 会变。</p><p><span class="marginnote">RFC 4821 针对黑洞。IPv6 最小链路 MTU 1280。本课不把每个 ICMP 代码背完。</span></p><h3 id="icmp-被滤则黑洞" tabindex="-1">ICMP 被滤则黑洞 <a class="header-anchor" href="#icmp-被滤则黑洞" aria-label="Permalink to &quot;ICMP 被滤则黑洞&quot;">​</a></h3><p>IPv6 必须发现。PLPMTUD 用传输探测。ECMP 与隧道使缓存失效。统一 MTU 可省掉发现。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：发大包 → ICMP → 降 MTU → 缓存。对照分片：中间分片与端到端发现，Saltzer 偏向端。隧道口应发 ICMP 或预先降低。</p>',11)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIG%5B%22DF%20%E5%A4%A7%E5%8C%85%22%5D%20--%3E%20DROP%5B%22%E4%B8%80%E8%B7%B3%E5%A4%AA%E5%B0%8F%22%5D%0A%20%20DROP%20--%3E%20ICMP%5B%22ICMP%20%E9%80%9A%E5%91%8A%20MTU%22%5D%0A%20%20ICMP%20--%3E%20CACHE%5B%22%E4%B8%BB%E6%9C%BA%E7%BC%93%E5%AD%98%22%5D%0A%20%20DROP%20--%3E%20BLK%5B%22%E6%97%A0%20ICMP%20%E5%88%99%E9%BB%91%E6%B4%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[P(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卫星与 5G 切片不改算法，只改 RTT，探测更慢。交换机巨帧不一致是二层版同一 bug。多播很少做 PMTUD，常用保守长度。安全：ICMP 可被伪造来缩小 MTU 做攻击，主机要合理性检查。</p><p>与容量无关：MTU 摊头税，不提高 \\(C\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPv6 原子分片扩展头的全部争议。TTL 与 traceroute 是下一课。后课默认：路径 MTU 靠 ICMP 或传输探测；过滤 ICMP 要给发现留洞。</p><p>数据中心可全路径统一 9000，省掉发现，这是运营契约。</p><p>上一课留下的缺口在本课收口；「路径 MTU 发现」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ttl-traceroute">TTL 与 traceroute</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DF + ICMP 发现最小 MTU；IPv6 必须。</li><li>ICMP 被滤则黑洞，用 PLPMTUD。</li><li>隧道与 ECMP 使缓存失效。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1191；RFC 8201；RFC 4821。</li></ul>',10))])}const E=i(M,[["render",c]]);export{_ as __pageData,E as default};
